WITH account_totals AS (SELECT account_id, AVG(amount) AS avg_amount, COUNT(CASE WHEN txn_type = 'CREDIT' THEN 1 END) AS credit_count FROM transactions WHERE txn_type IN ('REFUND', 'CREDIT') GROUP BY account_id) SELECT a.id, a.account_type, a.balance, at.avg_amount, at.credit_count FROM accounts a INNER JOIN account_totals at ON a.id = at.account_id WHERE at.credit_count > 6;
